HARNESS = 'pub use c6_core::unit;\nuse c6_core::game_free_cities::{Manager, Error};\ntrait Projection { fn project(&self, out:&mut Vec<u8>); }\nmacro_rules! scalar { ($($t:ty),*) => { $(impl Projection for $t { fn project(&self,o:&mut Vec<u8>){o.extend_from_slice(&self.to_le_bytes());} })* }; }\nscalar!(u8,u32,i32);\nimpl<T:Projection> Projection for Vec<T> { fn project(&self,o:&mut Vec<u8>){(self.len() as u32).project(o);for v in self {v.project(o);}} }\nimpl Projection for c6_core::game_free_cities::HashBool {fn project(&self,o:&mut Vec<u8>){self.definition_hash.project(o);self.value_raw.project(o);}}\nimpl Projection for c6_core::game_free_cities::PlotCoord {fn project(&self,o:&mut Vec<u8>){self.x.project(o);self.y.project(o);}}\nimpl Projection for c6_core::game_free_cities::Instance {fn project(&self,o:&mut Vec<u8>){self.player_ordinal.project(o);self.city_index.project(o);self.city_location.project(o);self.living_raw.project(o);self.turns_since_last_unit.project(o);self.urban_defenses.project(o);self.retaliation_target_ordinal.project(o);self.retaliation_behavior_tree.project(o);self.buildable_units.project(o);self.buildable_walls.project(o);}}\nimpl Projection for c6_core::game_free_cities::Manager {fn project(&self,o:&mut Vec<u8>){self.player_ordinal.project(o);self.control_priority_ordinal.project(o);self.instances.project(o);}}\nfn main() {\n    let input = std::fs::read(std::env::args().nth(1).unwrap()).unwrap();\n    let mut pos = 0;\n    let mut records = 0;\n    while pos < input.len() {\n        let size = u32::from_le_bytes(input[pos..pos+4].try_into().unwrap()) as usize;\n        let items = u32::from_le_bytes(input[pos+4..pos+8].try_into().unwrap()) as usize;\n        pos += 8;\n        let nv = u32::from_le_bytes(input[pos..pos+4].try_into().unwrap()) as usize;\n        let nc = u32::from_le_bytes(input[pos+4..pos+8].try_into().unwrap()) as usize;\n        pos += 8;\n        let sites:Vec<usize> = input[pos..pos+4*(nv+nc)].chunks_exact(4)\n            .map(|b| u32::from_le_bytes(b.try_into().unwrap()) as usize).collect();\n        pos += 4*(nv+nc);\n        let raw = &input[pos..pos+size]; pos += size;\n        let projection_size=u32::from_le_bytes(input[pos..pos+4].try_into().unwrap()) as usize;pos+=4;\n        let expected_projection=&input[pos..pos+projection_size];pos+=projection_size;\n        let limits = unit::Limits { max_bytes: size, max_items: items };\n        let value = Manager::decode(raw, limits).unwrap();\n        let mut projection=Vec::new();value.project(&mut projection);assert_eq!(projection,expected_projection);\n        for offset in sites {\n            let mut bad = raw.to_vec();\n            bad[offset..offset+4].copy_from_slice(&u32::MAX.to_le_bytes());\n            assert!(Manager::decode(&bad, limits).is_err());\n        }\n        assert_eq!(value.encode(limits).unwrap(), raw);\n        assert_eq!(value.encode_with_items(limits).unwrap(), (raw.to_vec(), items));\n        assert_eq!(Manager::decode_prefix(raw, limits).unwrap(), (value.clone(), size));\n        for end in (0..size.min(1024)).chain((0..1024).map(|i| i * size / 1024)).chain([size-1]) { assert!(Manager::decode(&raw[..end], limits).is_err()); }\n        let short = unit::Limits { max_bytes: size-1, ..limits };\n        assert_eq!(Manager::decode(raw, short), Err(Error::ResourceLimit));\n        assert_eq!(value.encode(short), Err(Error::ResourceLimit));\n        if items > 0 {\n            let short = unit::Limits { max_items: items-1, ..limits };\n            assert_eq!(Manager::decode(raw, short), Err(Error::ResourceLimit));\n            assert_eq!(value.encode(short), Err(Error::ResourceLimit));\n        }\n        let mut suffix = raw.to_vec(); suffix.push(77);\n        assert_eq!(Manager::decode(&suffix, limits), Err(Error::Trailing));\n        assert_eq!(Manager::decode_prefix_with_items(&suffix, limits).unwrap(), (value, size, items));\n        records += 1;\n    }\n    println!("{records}");\n}\n'
def current_record(raw):
    pos, items = 0, 0
    reconstructed, projection = bytearray(), bytearray()
    children, versions, counts = [], [], []
    schemas={name:(version,fields) for name,version,fields in SCHEMAS}
    def take(fmt, project=True):
        nonlocal pos
        width=struct.calcsize('<'+fmt)
        values=struct.unpack_from('<'+fmt,raw,pos)
        data=struct.pack('<'+fmt,*values);reconstructed.extend(data)
        if project:projection.extend(data)
        pos+=width
        return values[0] if len(values)==1 else list(values)
    def count(minimum=1):
        nonlocal items
        counts.append(pos);n=take('I');items+=n
        if n>(len(raw)-pos)//minimum:raise ValueError('hostile count')
        return n
    def value(ty):
        if ty.startswith('Vec<'):
            inner=ty[4:-1]
            return [value(inner) for _ in range(count({'u8':1,'i16':2,'i32':4,'u32':4,'ComponentId':8,'WeightedPlayer':8,'Instance':45,'HashBool':5,'ClanPlayerStats':48,'UniqueUnitClaimData':16,'CampLocation':8}.get(inner,4)))]
        if ty in ('u8','i16','i32','u32'):return take({'u8':'B','i16':'h','i32':'i','u32':'I'}[ty])
        begin=pos;version,fields=schemas[ty]
        if version:
            versions.append(pos)
            if take('I',False)!=version:raise ValueError('version differs')
        result={field:value(nested) for field,nested in fields}
        if ty=='Instance':children.append(dict(owner='GameCore::FreeCities::Instance',start=begin,end=pos))
        return result
    projected=value('Manager')
    if pos!=len(raw) or reconstructed!=raw:raise ValueError('complete typed reconstruction differs')
    return dict(bytes=pos,items=items,children=children,version_offsets=versions,count_offsets=counts,
        projection_sha256=sha(json.dumps(projected,sort_keys=True,separators=(',',':')).encode()),
        projection_bytes=bytes(projection),instances=len(projected['instances']),
        unit_entries=sum(len(x['buildable_units']) for x in projected['instances']),
        building_entries=sum(len(x['buildable_walls']) for x in projected['instances']))

def candidate(pin, records):
    pin = subprocess.check_output(['git', 'rev-parse', pin+'^{commit}'], cwd=ROOT, text=True).strip()
    archive = subprocess.check_output(['git', 'archive', pin], cwd=ROOT)
    with tempfile.TemporaryDirectory(prefix='c6-free-cities-wire-') as directory:
        tmp = Path(directory)
        source = tmp/'source'
        source.mkdir()
        subprocess.run(['tar', '-x', '-C', str(source)], input=archive, check=True)
        driver = source/'tools/linux/game_free_cities_audit.py'
        if driver.read_bytes() != Path(__file__).read_bytes():
            raise ValueError('actual audit driver must be committed with candidate')
        module = source/'crates/c6-core/src/game_free_cities.rs'
        lib = source/'crates/c6-core/src/lib.rs'
        if 'pub mod game_free_cities;' not in lib.read_text():
            raise ValueError('candidate archive must already export game_free_cities')
        source_paths = ['Cargo.toml', 'Cargo.lock', 'crates/c6-core/Cargo.toml',
                        'tools/linux/game_free_cities_audit.py', 'tools/linux/player_wmds_audit.py']
        source_paths += [str(path.relative_to(source)) for path in
                         sorted((source/'crates/c6-core').rglob('*.rs'))]
        source_hashes = {}
        for path in source_paths:
            archived = (source/path).read_bytes()
            committed = subprocess.check_output(['git', 'show', pin+':'+path], cwd=ROOT)
            if archived != committed:
                raise ValueError('archived source differs from Git pin: '+path)
            source_hashes[path] = sha(archived)
        subprocess.run(['cargo', 'test', '--offline', '-p', 'c6-core', 'game_free_cities::tests'], cwd=source, check=True)
        subprocess.run(['cargo', 'clippy', '--offline', '-p', 'c6-core', '--all-targets', '--', '-D', 'warnings'], cwd=source, check=True)
        subprocess.run(['cargo', 'build', '--offline', '--release', '-p', 'c6-core'], cwd=source, check=True)
        harness = HARNESS
        (tmp/'candidate.rs').write_text(harness)
        command = ['rustc', '--edition=2021', '-Dwarnings', '-O', str(tmp/'candidate.rs'),
                   '--extern', 'c6_core='+str(source/'target/release/libc6_core.rlib'),
                   '-L', 'dependency='+str(source/'target/release/deps')]
        subprocess.run(command+['-o', str(tmp/'candidate')], check=True)
        (tmp/'records').write_bytes(records)
        n = int(subprocess.check_output([str(tmp/'candidate'), str(tmp/'records')], text=True).strip())
        if n != 2:
            raise ValueError('candidate record count differs')
        for path, digest in source_hashes.items():
            if sha((source/path).read_bytes()) != digest or sha(subprocess.check_output(['git', 'show', pin+':'+path], cwd=ROOT)) != digest:
                raise ValueError('candidate build mutated archived source: '+path)
        return dict(source_commit=pin, archive_sha256=sha(archive),
                    module_sha256=sha(module.read_bytes()), driver_sha256=sha(driver.read_bytes()),
                    harness_sha256=sha(harness.encode()), executable_sha256=sha((tmp/'candidate').read_bytes()),
                    records=n, source_tests=3, strict_clippy=True, full_typed_projection_compared=True,
                    isolated_export_added=False, source_files_sha256=source_hashes,
                    every_source_hash_verified_against_git_pin=True, actual_exported_crate_tests=True,
                    candidate_uses_exported_crate=True, archive_source_mutations=False,
                    exact_byte_and_shared_item_caps=True, bounded_native_hostile_counts_and_versions=True, bounded_native_truncations_rejected=True,
                    short_byte_and_item_caps_rejected=True, strict_trailing_rejected=True,
                    exact_prefix_consumption=True)


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--assets',type=Path,default=ROOT.parent/'c6-assets-linux')
    p.add_argument('--private-root',type=Path,default=ROOT.parent/'c6-ghidra')
    p.add_argument('--source-commit',required=True)
    p.add_argument('--output',type=Path,required=True)
    args=p.parse_args()
    elf=Elf(args.assets/'libGameCore_XP2.so',GAME_SHA)
    dwarf=''.join(subprocess.check_output(['gdb','-nx','-batch',str(args.assets/'libGameCore_XP2.so'),'-ex',"ptype /o '"+name+"'"],text=True)for name in DWARF_NAMES)
    if sha(dwarf.encode())!=DWARF_SHA:raise ValueError('DWARF types differ')
    relocations=relocation_symbols(elf)
    for site,plt,body in BINDINGS:
        elf.call(site,plt);stub=elf.read(plt,6)
        if stub[:2]!=b'\xff\x25' or relocations.get(plt+6+struct.unpack_from('<i',stub,2)[0])!=body:raise ValueError('outer call binding differs')
    for a,n,name,digest in METHODS:
        if __import__("hashlib").sha256(elf.read(a,n)).hexdigest() != digest: raise ValueError('method identity differs: '+name)
    corpus=bytearray();fixtures=[]
    for identity,trace_name,trace_digest in FIXTURES:
        data=gzip.decompress((args.private_root/'evidence/linux-game-load/canonical'/(identity+'.bin.gz')).read_bytes())
        trace=gzip.decompress((args.private_root/'evidence/linux-save-normalization/checkpoint-203-owners'/trace_name).read_bytes())
        if sha(data)!=identity or sha(trace)!=trace_digest:raise ValueError('fixture identity differs')
        owners=[r for r in map(json.loads,trace.splitlines()) if r.get('event')=='owner' and r.get('save')==1]
        rows=[r for r in owners if r['owner']=='GameCore::FreeCities::Manager']
        if len(rows)!=1:raise ValueError('FreeCities::Manager cardinality differs')
        row=rows[0];raw=data[row['start']:row['end']];result=current_record(raw)
        children=[dict(owner=r['owner'],start=r['start']-row['start'],end=r['end']-row['start']) for r in owners if r['parent']==row['call']]
        if result.pop('children')!=children:raise ValueError('typed child extents differ')
        all_nested=[dict(owner=r['owner'],start=r['start']-row['start'],end=r['end']-row['start']) for r in owners if r['call']!=row['call'] and row['start']<=r['start'] and r['end']<=row['end']]
        if all_nested!=children:raise ValueError('unverified nested native owner cut')
        next_rows=[r for r in owners if r['start']==row['end'] and r['owner']=='GameCore::Random']
        if len(next_rows)!=1:raise ValueError('next Random boundary differs')
        versions=result['version_offsets'];counts=result['count_offsets']
        versions=[versions[i] for i in sorted({0,len(versions)-1}|{i*len(versions)//64 for i in range(64)})]
        counts=[counts[i] for i in sorted({0,len(counts)-1}|{i*len(counts)//64 for i in range(64)})]
        corpus.extend(struct.pack('<IIII',len(raw),result['items'],len(versions),len(counts)))
        for site in versions+counts:corpus.extend(struct.pack('<I',site))
        corpus.extend(raw)
        projection=result.pop('projection_bytes');corpus.extend(struct.pack('<I',len(projection)));corpus.extend(projection)
        result['version_sites']=len(result.pop('version_offsets'));result['count_sites']=len(result.pop('count_offsets'))
        result.update(core_sha256=identity,trace_sha256=trace_digest,wire_sha256=sha(raw),start=row['start'],end=row['end'],direct_children=dict(Counter(c['owner'] for c in children)),all_nested_native_cuts_compared=True,next_owner=dict(owner=next_rows[0]['owner'],start=next_rows[0]['start'],end=next_rows[0]['end']))
        fixtures.append(result)
    report=dict(schema='c6-linux-game-free-cities-v1',checks_passed=True,gamecore_sha256=GAME_SHA,
        methods=[dict(address=hex(a),size=n,name=s,sha256=h) for a,n,s,h in METHODS],dwarf_sha256=DWARF_SHA,outer_bindings=[dict(site=hex(a),plt=hex(b),body=hex(c)) for a,b,c in BINDINGS],fixtures=fixtures,
        candidate=candidate(args.source_commit,corpus) if args.source_commit else None,
        complete_observed_free_cities_records=True,complete_current_free_cities_structural_fields=True,complete_current_free_cities_wire=True,original_execution=False,private_writes=False,
        native_read_side_effects=False,full_player=False,gameplay_state=False,world_import=False,actions=False,turns=False,
        unknown_save_bytes_masked=False,recorded_raw_save_load_difference_bytes=89198,next_component='GameCore::Random')
    args.output.write_text(json.dumps(report,indent=2)+'\n')
if __name__=='__main__':main()
